select  pdgi.id,pdgi.product_demand_id,pdgi.product_demand_group_id,pdgi.position,pdgi.version, pdgi.create_man,pdgi.create_man_id,pdgi.create_date,pdgi.modify_date,
a.name,a.priority,a.owner,a.owner_id,a.status, a.product_line_id,a.type, a.expect_schedule_time,a.create_man as demandCreateMan,a.create_man_id as demandCreateManId,
a.create_date as demandCreateDate,a.modify_date as demandModifyDate,c.name productLineName,d.name bizDomainName, a.ued_time, a.transfer_time, a.back_time,
a.front_time, a.qa_time, a.total_time

    ,e.user_name copier

from product_demand_group_item pdgi
left join product_demand a on pdgi.product_demand_id=a.id
left join product_line c on a.product_line_id=c.id
left join biz_domain d on c.biz_domain_id=d.id

    left join person e on a.id=e.main_id and e.type =20 and e.is_deleted =false


    pdgi.product_demand_group_id = #{groupId}
    and pdgi.is_deleted =false
    and a.id = #{id}
    and a.name like concat('%',#{name},'%')
    and e.user_id = #{copierId}

        and a.create_date >= #{createDateStart} and a.create_date <= #{createDateEnd}


        and a.modify_date >= #{modifyDateStart} and a.modify_date <= #{modifyDateEnd}


        and a.expect_schedule_time >= #{expectScheduleTimeStart} and a.expect_schedule_time <= #{expectScheduleTimeEnd}


        and a.priority in

            #{item}



        and c.id in

            #{item}



        and d.id in

            #{item}



        and a.owner_id in

            #{item}



        and a.status in

            #{item}



        and a.id not in

            #{item}



        and a.id  in

            #{item}



        and a.id not in

            #{item}



        and a.type REGEXP CONCAT('[', #{types},']')

    and  a.is_deleted =false
    order by pdgi.`position` desc

select a.id,a.name,a.priority,a.owner,a.owner_id,a.status, a.product_line_id,
a.create_man,a.create_man_id,a.create_date,a.modify_date, a.type, a.expect_schedule_time,
c.name productLineName ,d.name bizDomainName

    ,e.user_name copier

from product_demand a
left join product_line c on a.product_line_id=c.id
left join biz_domain d on c.biz_domain_id=d.id
left join biz_domain_group_relation e on d.id = e .biz_domain_id

    left join person e on a.id=e.main_id and e.type =20 and e.is_deleted =false


    and a.id = #{id}
    and a.name like concat('%',#{name},'%')
    and e.user_id = #{copierId}

        and a.create_date >= #{createDateStart} and a.create_date <= #{createDateEnd}


        and a.modify_date >= #{modifyDateStart} and a.modify_date <= #{modifyDateEnd}


        and a.expect_schedule_time >= #{expectScheduleTimeStart} and a.expect_schedule_time <= #{expectScheduleTimeEnd}


        and a.priority in

            #{item}



        and c.id in

            #{item}





        and e.biz_domain_group_id = #{bizDomainGroupId}


        and a.owner_id in

            #{item}



        and a.status in

            #{item}



        and a.id not in

            #{item}



        and a.id  in

            #{item}



        and a.id not in

            #{item}



        and a.type REGEXP CONCAT('[', #{types},']')

    and  a.is_deleted = false
    and  c.is_deleted = false
    and  d.is_deleted = false
    and  e.is_deleted = false
    and not exists (
        select 1 from product_demand_group_item pdgi
        where pdgi.product_demand_id  = a.id and pdgi.is_deleted = false
    )

select * from product_demand_group_item
where is_deleted = false
and id = #{id}
and product_demand_group_id = #{groupId}

select pdgi.* from product_demand_group_item pdgi
where  pdgi.is_deleted = false
  and pdgi.product_demand_id = #{demandId}
  and pdgi.product_demand_group_id = #{groupId}

select pdgi.* from product_demand_group_item pdgi
where  pdgi.is_deleted = false
and pdgi.product_demand_id = #{demandId}

select *
from product_demand_group_item
where product_demand_group_id = #{productDemandGroupId}
  and is_deleted = false
  and `position` > #{position}
order by `position` asc limit 1

select *
from product_demand_group_item
where product_demand_group_id = #{productDemandGroupId}
  and is_deleted = false
  and `position` < #{position}
order by `position` desc limit 1
